const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } = require("docx");

function h(text, level) {
  return new Paragraph({ text, heading: level, spacing: { before: 240, after: 120 }, keepNext: true });
}
function p(text, opts = {}) {
  return new Paragraph({ children: [new TextRun({ text, ...opts })], spacing: { before: 0, after: 120 } });
}
function label(text) {
  return new Paragraph({ children: [new TextRun({ text, bold: true })], spacing: { before: 200, after: 60 } });
}

const children = [];

children.push(new Paragraph({ text: "FedFACS — Additional Replacements 15–22", heading: HeadingLevel.TITLE, spacing: { after: 120 } }));
children.push(p("Continuation of the 14-replacement revision companion. These replacements are textual/notational/interpretive corrections that do not require re-running experiments. Each closes a specific reviewer comment honestly — either by fixing the writing to match what the data and equations actually support, or by adding an explicit, scoped disclosure where a claim cannot be substantiated without the original code and datasets.", { italics: true }));

// Replacement 15
children.push(h("Replacement 15. Abstract corrections", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("Abstract.   |   Reviewer comments addressed: R2-11 (and the overreach implicit in R1's framing of aggregate claims)."));
label("Before");
children.push(p("“...FedFACS achieves average improvements of 1.39% in accuracy, 1.41% in F1-score, and 0.44% in recall, as well as 3.47% fewer selected clients while maintaining comparable communication rounds, in addition to improving fairness by an average of 1.38% in Jain’s Fairness Index (JFI), relative to the best performing existing method...”"));
label("After");
children.push(p("Relative to the strongest baseline in each configuration (Zhai et al. in Configuration A, AHIBCS in Configuration B, FedFairCS in Configuration C — these are three different comparators, not one common method), FedFACS shows dataset-dependent gains: accuracy improves in most but not all settings, F1-score improves consistently, and recall improves on FMNIST and CIFAR-10 but is lower than AHIBCS on COVID-19 (0.934 vs 0.948); the signed average therefore mixes a gain and a loss rather than representing a uniform improvement. Reported percentage gains are absolute accuracy-point differences unless stated otherwise as relative. Reductions in cumulative uploads range from 1.48% to 4.10% depending on dataset; communication-round counts are not uniformly reduced (FedFACS uses more rounds than AHIBCS on FMNIST and CIFAR-10). JFI gains average 1.29–1.47% across the two datasets evaluated in Configuration C, within the margins reported in Fig. 11. The abstract is revised to report per-configuration, per-dataset ranges rather than a single pooled average, and to avoid implying a single comparator was outperformed on every metric."));

// Replacement 16
children.push(h("Replacement 16. Fairness metric (JFI) interpretation", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("Fairness metric, Eq. (24)–(25) and surrounding discussion.   |   Reviewer comments addressed: R1-09; R2-15."));
label("Before");
children.push(p("“When JFI=1, it refers to equal participation for all clients, when the values in the range 0.5≤JFI<1 indicate that all clients participates with different times, and values below 0.5 represent the unfair participation.”"));
label("After");
children.push(p("Equation (24) applies Jain's index to the quality-adjusted ratio p_i/q_i, not to raw participation counts p_i. Consequently, JFI=1 means participation is proportional to the quality term q_i defined in Eq. (25) — equal participation only in the special case where every client has identical q_i. Because q_i depends on each client's label count and injected noise level, part of any reported fairness difference reflects selection correlating with data quality rather than with raw participation equality. The minimum attainable value of Eq. (24) is 1/n, not 0; the threshold of 0.5 used in the discussion is a descriptive convention adopted for this study and is not derived from the index's mathematical properties — it is not claimed to be a universal fairness boundary. We do not claim that an index between 0.5 and 1 guarantees every client is served: a quality-weighted index in that range is consistent with some clients never being selected, provided the quality term compensates. We now state these three points explicitly in place of the previous unqualified claims."));

// Replacement 17
children.push(h("Replacement 17. Algorithm, notation, and wording corrections", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("Section 4.1 (framework overview text), Eqs. (1)-(2), Eq. (8) clip operator, Algorithm 1 heading and inputs.   |   Reviewer comments addressed: R2-19; R2-20."));
label("Before (Sec. 4.1 wording)");
children.push(p("“...it prevents dominance among high-quality clients and ignores clients with smaller datasets or lower utility, which may contribute to global model performance and enhance generalization.”"));
label("After (Sec. 4.1 wording)");
children.push(p("“...it prevents dominance among high-quality clients and avoids permanently excluding clients with smaller datasets or lower utility, since such clients may still contribute to global model performance and enhance generalization.” The previous wording (“ignores clients with smaller datasets… which may contribute…”) stated the opposite of the intended meaning; the fairness mechanism's purpose is to include, not exclude, such clients over time."));
label("Before (clip operator)");
children.push(p("a_i^t = clip(a, 1, 0) = ∏_[0,1](...)"));
label("After (clip operator)");
children.push(p("The clipping operator is corrected to clip(a, 0, 1) = min{1, max{0, a}}, consistent with the stated codomain [0,1] (the published order of bounds was reversed)."));
label("Before (Eqs. 1-2 indexing)");
children.push(p("min_w F(w) = Σ_{i=1}^{N} (n_i/n)·f_i(w); f_i(w) = (1/n_i) Σ_{j∈d_i} l(w; x_i, y_i)"));
label("After (Eqs. 1-2 indexing)");
children.push(p("Eq. (2) is corrected to index the summed training example consistently with client i: f_i(w) = (1/n_i) Σ_{(x,y)∈D_i} l(w; x, y). The previous statement mixed index i (the client) with index j (the summation variable) while writing (x_i, y_i) outside the sum, which is undefined."));
label("Before (Algorithm 1 heading/inputs)");
children.push(p("“Algorithm 1 Stability-Weighted Federated Aggregation” ... “Update the local model parameters: w_i^t ← w_i^t − η∇L_local^t” ... Input “C⊂C”"));
label("After (Algorithm 1 heading/inputs)");
children.push(p("Algorithm 1 is retitled “Client-Side Fitness Evaluation and Local Training” (it is the client-side procedure; stability-weighted aggregation is performed server-side in Algorithm 2). L_local is defined as the empirical loss of Eq. (2) evaluated on the client's current mini-batch. The garbled input “C⊂C” is corrected to “C_k^t ⊂ C: the cohort selected by the server at round t.”"));

// Replacement 18
children.push(h("Replacement 18. Dataset-specific output heads and Conclusion corrections", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("Section 5.2 (Model), Section 6 (Conclusion).   |   Reviewer comments addressed: R1-17 (textual part); R2-21 (MNIST/FMNIST citation); R2-22."));
label("Before (Model)");
children.push(p("“...the layer 4 and the final fully connected layer are trained and adjusted for 10 classes.”"));
label("After (Model)");
children.push(p("The final fully connected layer is sized per dataset: 10 output classes for MNIST, FMNIST, and CIFAR-10, and 3 output classes for the COVID-19 Radiography dataset (COVID-19, normal, viral pneumonia), consistent with the class counts stated in Section 5.1. The earlier statement describing a uniform 10-class head applied only to the three 10-class datasets and did not account for the COVID-19 experiments; this is now stated explicitly rather than left as a blanket description."));
label("Before (Conclusion, dataset list)");
children.push(p("“Evaluation results across diverse benchmark datasets under various data partitioning scenarios show that the proposed FedFACS provides higher classification accuracy and speeds up convergence...” (no explicit dataset list; MNIST/FMNIST not named in-text elsewhere in the discussion; COVID-19 omitted from the Conclusion)."));
label("After (Conclusion, dataset list)");
children.push(p("“Evaluation results across MNIST, FMNIST, CIFAR-10, and the COVID-19 Radiography dataset, under various data partitioning scenarios, show that FedFACS provides higher classification accuracy on most evaluated dataset-scenario combinations and reduces cumulative aggregated-client uploads, while requiring more communication rounds than the fastest baseline in several settings (Section 5.3; Tables 2, 3, 5).” The Conclusion now names all four evaluated datasets and reflects the mixed trade-offs reported in Replacement 11 rather than an unqualified claim of superiority."));
label("Before (Conclusion, overreach language)");
children.push(p("“...maintaining a balance between informativeness and fairness... ensures fairness in client selection compared with the best-performing baseline methods... each component is crucial for balancing high model accuracy with low communication costs...”"));
label("After (Conclusion, overreach language)");
children.push(p("“...targets a balance between informativeness and fairness... improves measured fairness (JFI) relative to the compared baselines in most evaluated settings (Section 5.3, Table 6, Fig. 11)... the ablation results in Tables 1–2 indicate that adaptive aggregation and cohort sizing contribute to the reported gains in the tested conditions, though their effects are not individually isolated (see Limitations).” Claims of guaranteed fairness and of every component being universally beneficial are replaced with claims scoped to the evidence actually presented."));

// Replacement 19
children.push(h("Replacement 19. Reference list corrections", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("Reference list, entries [7], [14], [29], [13].   |   Reviewer comments addressed: R2-21."));
children.push(p("• Entry [14]: the in-text citation “He et al. 2021” for the ResNet architecture is corrected to “He et al. 2016” to match the reference-list entry (He K, Zhang X, Ren S, Sun J (2016) Deep residual learning for image recognition. CVPR, pp. 770–778)."));
children.push(p("• Entry [29] (Li et al. 2016, “Robust geometric lp-norm feature pooling for image classification and action recognition”) is removed from the reference list; it is not relevant to the cited context and was not discussed in the text where cited."));
children.push(p("• Entry [13]: the market-size statement is corrected to use consistent units matching the cited source title (“Federated learning market valuation to reach USD 311.4 billion by 2032”) throughout the Introduction; the previously stated “USD 133.1 million” / “USD 311.4 million” figures are corrected to – million/billion as given in the source, and the statement is attributed explicitly to a market-research press release rather than presented as an independently verified figure."));
children.push(p("• Entry [7] (Chaudhari et al. 2002, a power-systems control paper) is retained only as the origin of the general Lyapunov-function concept cited by analogy; the text accompanying this citation (see Replacement 6 and Replacement 21) now states explicitly that no Lyapunov function or stability proof is constructed for the control law in this manuscript, so the citation supports terminology, not a formal claim."));
children.push(p("• MNIST (LeCun et al., ref. [28]) and FMNIST (Xiao et al., ref. [53]) are added as explicit in-text citations in Section 5.1 (Datasets), where they were previously listed only in the reference list without an in-text citation."));

// Replacement 20
children.push(h("Replacement 20. Threat model and self-reported score disclosure", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("New paragraph, end of Section 4.1.   |   Reviewer comments addressed: R2-17."));
label("After (new text)");
children.push(p("“FedFACS, as described, assumes that clients report fitness scores, stability scores, and idle-round counts honestly. Because the server does not independently verify these self-reported values before using them for selection and aggregation weighting, a client that misreports its score can influence which clients are selected and how updates are weighted, without separate detection in the current design. This assumption is standard among comparably scored client-selection methods evaluated in this paper (e.g., Zhai et al. 2024; Liu et al. 2025), but it should be stated explicitly rather than left implicit. Verification mechanisms (e.g., cross-validated scoring, anomaly detection on reported scores, or Byzantine-robust aggregation) are not part of the current design and are identified as necessary future work in the Limitations section, not assumed to be solved by the present fitness-based mechanism.”"));

// Replacement 21
children.push(h("Replacement 21. Scale mismatch disclosure and no-convergence-guarantee statement", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("Eq. (9) discussion; control-mechanism description (Section 4.2).   |   Reviewer comments addressed: R2-05; R2-18."));
label("Before");
children.push(p("“The proposed control mechanism is inspired by the Lyapunov stability principle... the use of bounded and normalized updates helps ensure stable behavior during training.”"));
label("After");
children.push(p("“Equation (9) combines a_i^t·ΔKL_i^t and (1−a_i^t)·F_i^t directly, without rescaling. Because F_i^t ≥ 1 by construction (Eq. 6) while ΔKL_i^t is typically much smaller than 1 for well-trained models, the fairness term can dominate the priority score across most of the achievable range of a_i^t, limiting the practical effect of the control parameter. We disclose this scale mismatch explicitly rather than claiming balanced influence; a corrected design would rescale ΔKL_i^t and F_i^t to a common range (e.g., min-max or batch-relative normalization) before combination, but revalidating the controller under a rescaled formulation requires re-running the federated experiments and is left for future work (see Limitations). Separately, the control law in Eq. (8) is an exponential-moving-average feedback rule, bounded and clipped by construction; it is not a Lyapunov function, and this manuscript does not construct one or provide a stability proof. The term ‘Lyapunov-inspired’ is retained only to describe the qualitative feedback structure and is not a claim of proven convergence; no convergence rate or fairness bound is established for FedFACS in this work.”"));

children.push(h("Replacement 22. Limitations and Reproducibility Statement (new section, inserted before Section 6, Conclusion)", HeadingLevel.HEADING_2));
label("Manuscript location:");
children.push(p("New Section 5.4, immediately after Section 5.3 and before the Conclusion.   |   Reviewer comments addressed: R1-05 (empirical validation of the uncertainty penalty), R1-08 (byte-level communication accounting), R1-10 (selection-frequency distributions, worst-client analysis), R1-12 (quantitative novelty comparison), R1-13 (component-isolated ablations), R1-14 (baseline reproduction provenance), R1-15/R2-12 (statistical significance), R1-16 (implementation detail disclosure), R1-18 (Configuration B bounds and per-round logs), R1-21/R2-23 (reproducibility package), R2-01 (downlink/compute cost measurement), R2-10 (confusion matrices), R2-13 (incomplete ablation), R2-14 (unevaluated baselines), R2-15 (client-level fairness), R2-16 (sensitivity and scalability analysis)."));
label("After (new text)");
children.push(p("“The results reported in Section 5.3 have the following scope and limitations, disclosed here rather than presented as resolved:"));
children.push(new Paragraph({ children: [new TextRun({ text: "1. Statistical significance. ", bold: true }), new TextRun({ text: "All reported accuracy, fairness, and round-to-target values reflect a single training run per configuration. No multiple-seed runs, standard deviations, or confidence intervals are reported. Differences on the order of 1–3 rounds or under 1 accuracy point, in particular, should be read as descriptive rather than statistically established. A rigorous comparison requires at least five independently seeded runs per method with matched partitions, which was not performed for this submission." })], spacing: { after: 100 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "2. Component-isolated ablation. ", bold: true }), new TextRun({ text: "The ablation in Tables 1–2 (FedFACS-A1, FedFACS-A2) varies cohort sizing and aggregation jointly; it does not isolate the individual contributions of the KL-based utility term, the fairness term, the uncertainty penalty, or the adaptive control parameter. In particular, FedFACS-A1 is slower than Zhai et al. (2024) on several CIFAR-10 and MNIST settings (Table 2), indicating that the selection mechanism alone does not account for all reported gains; the remaining gains cannot currently be attributed to a specific component." })], spacing: { after: 100 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "3. Communication and computation accounting. ", bold: true }), new TextRun({ text: "Cumulative aggregated-client counts (Eq. 23, Table 5) count only clients whose updates were uploaded and aggregated. Under Algorithms 1–2, every candidate client downloads the global model, trains locally, and computes a fitness score before selection occurs; these downlink, training, and scoring costs are not separately measured or reported. The reported upload-count reductions therefore characterize one component of communication cost, not total transmitted bytes, total compute, or wall-clock training time." })], spacing: { after: 100 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "4. Client-level and quality-adjusted fairness. ", bold: true }), new TextRun({ text: "JFI (Eq. 24) is computed on the quality-adjusted ratio p_i/q_i, where q_i depends on each client's label count and injected noise level (Eq. 25); part of any reported fairness difference may reflect selection correlating with data quality. Per-client accuracy variance, worst-performing-client accuracy, and the distribution of selection frequency across clients are not reported in this submission." })], spacing: { after: 100 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "5. Baseline provenance and additional comparators. ", bold: true }), new TextRun({ text: "It is not stated for every baseline in every configuration whether results were reproduced under this paper's implementation and architecture or taken from the cited publication under its own architecture and preprocessing; this should be assumed to vary by baseline unless stated otherwise in a future revision. Oort, FedCor, q-FFL/AFL, SCAFFOLD, and FedNova are discussed in Section 2 but not evaluated experimentally in this paper." })], spacing: { after: 100 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "6. Recall/F1 reconciliation. ", bold: true }), new TextRun({ text: "Table 4 reports recall and F1-score values whose relationship to the corresponding accuracy figures (Table 3, Figs. 8–9) has not been independently re-verified against raw confusion matrices in this submission, and the averaging convention (macro, micro, or weighted) used to compute them is not stated. These values should be treated as reported rather than independently re-derived pending release of the underlying confusion matrices." })], spacing: { after: 100 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "7. Sensitivity and scalability. ", bold: true }), new TextRun({ text: "No sensitivity analysis is reported for β, λ, μ, γ, the scoring-batch count B, or (C_kmin, C_kmax); no experiments beyond 100 simulated clients were run, and no runtime, memory, or wall-clock scalability analysis is reported." })], spacing: { after: 100 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "8. Reproducibility package. ", bold: true }), new TextRun({ text: "The code and dataset partitions used to produce the results in this submission are not available to be released alongside this revision. We acknowledge this is a substantive limitation for independent verification of the specific numbers reported, and we recommend that the quantitative claims in Sections 5.2–5.3 be weighted accordingly until a reproducibility package (configuration files, partition identifiers, seeds, per-round scores, cohort selections, and aggregation weights) can be produced and released.”" })], spacing: { after: 100 } }));

const doc = new Document({
  sections: [{
    properties: { page: { size: { width: 12240, height: 15840 } } },
    children,
  }],
  styles: {
    default: {
      heading1: { run: { font: "Calibri", size: 32, bold: true }, paragraph: { spacing: { before: 240, after: 120 }, keepNext: true } },
      heading2: { run: { font: "Calibri", size: 26, bold: true }, paragraph: { spacing: { before: 240, after: 120 }, keepNext: true } },
      document: { run: { font: "Calibri", size: 22 } },
    },
  },
});

Packer.toBuffer(doc).then((buf) => {
  require("fs").writeFileSync("FedFACS_Additional_Replacements_15-22.docx", buf);
  console.log("written");
});

