const { Document, Packer, Paragraph, TextRun, HeadingLevel } = require("docx");

function h(text, level) {
  return new Paragraph({ text, heading: level, spacing: { before: 240, after: 120 }, keepNext: true });
}
function p(text, opts = {}) {
  return new Paragraph({ children: [new TextRun({ text, ...opts })], spacing: { before: 0, after: 80 } });
}
function row(tag, comment, resolution, kind) {
  const out = [];
  out.push(new Paragraph({ children: [new TextRun({ text: `${tag}. `, bold: true }), new TextRun({ text: comment, italics: true })], spacing: { before: 160, after: 40 } }));
  const tagText = kind === "fixed" ? "Resolved — " : kind === "disclosed" ? "Disclosed as limitation — " : "Resolved (text/notation only) — ";
  out.push(new Paragraph({ children: [new TextRun({ text: tagText, bold: true }), new TextRun({ text: resolution })], spacing: { after: 100 } }));
  return out;
}

const children = [];
children.push(new Paragraph({ text: "Response to Reviewers — FedFACS", heading: HeadingLevel.TITLE, spacing: { after: 80 } }));
children.push(p("Manuscript: “FedFACS: A Fair Adaptive Client Selection Framework for Communication-Efficient Federated Learning”, Journal of King Saud University — Computer and Information Sciences.", { italics: true }));
children.push(p("We thank both reviewers for a detailed and technically precise review. Every point raised is addressed below. Points that concern the mathematical formulation, algorithm description, terminology, or interpretation of existing results are corrected directly (via the numbered Replacements in the accompanying revision documents). Points that require new experiments, additional seeds, raw confusion matrices, per-round logs, or code/data that are not currently available to us are not answered with invented numbers; they are instead disclosed explicitly in the new Limitations and Reproducibility Statement (Replacement 22) and flagged below as such. We believe this is the only honest way to respond to those specific requests at this time, and we have scoped the manuscript's claims so that they do not exceed what the reported evidence supports.", { bold: true }));

children.push(h("Reviewer 1", HeadingLevel.HEADING_1));

const r1 = [
  ["R1-01", "Equation (7) never increments the idle-round counter for an unselected client, so the fairness mechanism as written cannot produce the described behavior.", "Eq. (7) is corrected: unselected clients increment their counter by 1, selected clients reset to 0 (Replacement 4).", "fixed"],
  ["R1-02", "The control law denominator in Eq. (8) can be zero or negative, and the claimed direction of the feedback does not hold in general.", "The denominator is changed to λF_i^t, which is always positive since F≥ 1 (Replacement 6). The directional claim is also corrected to state that the sign depends jointly on ν^t and (ΔKL_i^t−F_i^t), not on ν^t alone.", "fixed"],
  ["R1-03", "The stability-weighted aggregation permits negative weights, the normalization in Eq. (18) does not guarantee nonnegative weights or a nonzero denominator, and Eq. (4)/Algorithm 2 use unnormalized scores while Eqs. (17)–(18) use normalized ones.", "Aggregation is redefined using the positive part of each raw score with a sample-count fallback when the sum of positive parts is zero (Replacement 8). Eqs. (4) and (17) are stated to use the same weighted average.", "fixed"],
  ["R1-04", "The utility interpretation (expected reduction in KL divergence) is not supported by the actual definition, which measures post-training disagreement, not a before/after reduction.", "Eq. (5) and surrounding text are corrected to describe ΔKL as a measure of post-training local/global disagreement, not a reduction or evidence of improvement (Replacement 5).", "fixed"],
  ["R1-05", "The uncertainty penalty (batch variance) does not clearly distinguish noisy/corrupted data from legitimate heterogeneity.", "The interpretive text is corrected to state only what the variance term measures (dispersion across scoring batches), without the unsupported claim that low variance establishes reliability (Replacement 5). Whether the penalty actually discriminates corrupted from heterogeneous-but-useful updates is an empirical question; we do not have the ability to test this without the original client data pipelines, so it is disclosed as an open item in the Limitations section (Replacement 22, item 2).", "disclosed"],
  ["R1-06", "The cohort-size rule (Eqs. 15–16) can produce invalid (negative, non-integer, out-of-bound) cohort sizes.", "Eq. (16) now clips the loss ratio and rounds to the nearest integer within [C_kmin, C_kmax] (Replacement 7); Eq. (15) is redefined as a causal, bounded quantity (Replacement 3).", "fixed"],
  ["R1-07", "The reference convergence trajectory (Eq. 11) depends on a prior run of a competing baseline, which is unavailable in practice and creates circularity with the comparison.", "Eq. (11) is replaced with a causal self-reference computed from FedFACS's own prior rounds via an exponential moving average, removing the dependency on a competitor's trajectory (Replacement 3).", "fixed"],
  ["R1-08", "The communication-efficiency claim is not established by counting only aggregated updates; all candidates download the model and train locally regardless of final selection.", "The protocol description now explicitly states that all N candidates incur download, training, and scoring costs, and that only upload is reduced (Replacement 2). The resource-accounting equations are extended to define download/upload/auxiliary traffic terms (Replacement 10). Measuring and reporting actual byte-level costs requires re-running the experiments with instrumentation that does not exist in the recovered materials; this is disclosed explicitly rather than estimated (Replacement 22, item 3).", "disclosed"],
  ["R1-09", "Jain's index (Eq. 24) is applied to a quality-adjusted ratio, so JFI=1 does not mean equal raw participation, and the 0.5 threshold is not justified.", "The interpretation is corrected: JFI=1 means participation proportional to quality q_i, not raw equality; the 0.5 threshold is now stated as a descriptive convention, not a derived property; the claim that an index in [0.5,1) implies every client participates is removed (Replacement 16).", "fixed"],
  ["R1-10", "Claims of preventing starvation and preserving fairness exceed the evidence, since the utility–fairness coefficient can reach 1 and selection does not guarantee meaningful aggregation influence.", "Overreaching language in the Conclusion is scoped to what is shown (Replacement 18). Selection-frequency distributions, maximum waiting times, and cumulative aggregation influence per client are not available without the original logs; this is disclosed explicitly (Replacement 22, item 4) rather than asserted.", "disclosed"],
  ["R1-11", "The aggregation rule is not shown to relate to the stated optimization objective (Eq. 1), and Eq. (3) is not a complete subset-selection formulation.", "Eqs. (1)–(3) are rewritten to state the sample-weighted objective precisely, define the fitness-maximization selection rule over the cohort size from Eq. (16), and explicitly note that Eq. (1) is the reference population objective, not the ranking rule's optimization criterion (Replacement 1).", "fixed"],
  ["R1-12", "The novelty discussion does not identify a precise contribution beyond combining known adaptive mechanisms, and does not compare decision rules, information requirements, or costs directly against AHIBCS and FedFairCS.", "We can and do tighten the textual novelty framing to avoid overstating distinctiveness (reflected in the corrected Conclusion, Replacement 18). A rigorous head-to-head comparison of decision rules, information requirements, and measured computational cost against AHIBCS/FedFairCS under one common framework is an experimental undertaking we cannot perform without the original implementation; this is disclosed as future work (Replacement 22, item 5).", "disclosed"],
  ["R1-13", "The two-variant ablation (A1, A2) does not isolate KL utility, the fairness term, the uncertainty penalty, the controller, or the baseline-derived reference individually.", "The ablation discussion is corrected to state precisely what A1/A2 vary (cohort sizing and aggregation jointly) and what they do not isolate (Replacement 13). Targeted single-component ablations require new training runs and are disclosed as not performed (Replacement 22, item 2).", "disclosed"],
  ["R1-14", "Baseline comparisons need clearer provenance (reproduced vs. copied from source papers) and consistent naming (Pow-D vs. FedProx in Configuration B).", "Replacement 14 states exactly which methods are compared in each configuration and their stated hyperparameters; the Pow-D/FedProx naming inconsistency is corrected throughout (Replacement 11/14). Whether every individual baseline number was reproduced under this paper's own implementation versus taken from its source publication is not something we can state with certainty without the original experiment logs; this is disclosed rather than asserted either way (Replacement 22, item 5).", "disclosed"],
  ["R1-15", "No independent runs or uncertainty estimates are reported; it is unclear whether reported accuracy is final-round, best-observed, or averaged.", "The evaluation-endpoint protocol is now stated precisely (round-to-target on a defined split; final vs. peak vs. checkpoint accuracy are distinguished and not interchanged; unattained targets are recorded as “not reached”) (Replacement 12). Multi-seed statistical reporting requires new training runs, which we cannot perform without the recovered code/data; this is disclosed explicitly as not yet done (Replacement 22, item 1).", "disclosed"],
  ["R1-16", "Implementation details are missing: ResNet-18 pretraining checkpoint, preprocessing, grayscale handling, batch-norm treatment, and hyperparameter initialization in every configuration.", "We can state the dataset-specific output-head sizes precisely (Replacement 18). The remaining low-level preprocessing/checkpoint details were not recorded in the materials available to us after the loss described above; rather than reconstruct them from memory, we disclose this as missing information to be supplied before the next revision if the original configuration can be recovered (Replacement 22, item 8).", "disclosed"],
  ["R1-17", "The COVID-19 dataset is described as 3-class, but the model description states a 10-class output head.", "The model description is corrected to specify a 3-class head for COVID-19 and a 10-class head for MNIST/FMNIST/CIFAR-10 (Replacement 18). Patient-level grouping, duplicate checks, and recall/F1 averaging convention for this dataset cannot be confirmed without the original data split; disclosed accordingly (Replacement 22, item 6).", "disclosed"],
  ["R1-18", "Configuration B participation counts (e.g., COVID-19: 1047/103≈10.17, exceeding the stated cap of 10) need reconciliation with disclosed per-configuration bounds and per-round logs.", "The cohort-sizing text now states explicitly that the Configuration A bounds (8, 10) are not asserted to apply to Configuration B, and asks that configuration-specific bounds be disclosed (Replacement 7). Per-round cohort logs for Configuration B are not available in the recovered materials; disclosed as missing rather than reconciled by assumption (Replacement 22, item 8).", "disclosed"],
  ["R1-19", "The results discussion overstates trade-offs — e.g., FedFACS takes more rounds than AHIBCS on FMNIST for a small upload reduction, DivFL is faster on MNIST, and FedFACS does not win every Table 6 condition.", "Replacement 11 rewrites the Configuration B results discussion to state rounds-vs-uploads trade-offs plainly in both directions (more rounds, fewer uploads) rather than as unqualified improvement.", "fixed"],
  ["R1-20", "Specific reporting inconsistencies: FMNIST-S2 accuracy 83.80% (Table 1) vs. 83.08% (text); Fig. 9 mislabels percentage-point gains as relative percentages; ambiguity about whether 200-round entries mean target attainment or budget exhaustion.", "All three issues are corrected: the 83.80% figure is used consistently (Replacement 11); relative vs. absolute-point gains are now distinguished explicitly (Replacement 15); and the evaluation-endpoint protocol records “not reached” outcomes instead of treating budget exhaustion as success (Replacement 12).", "fixed"],
  ["R1-21", "The algorithms should be rewritten as one consistent, executable account (reset timing, when scores are computed, when counters update), and a reproducibility package is requested.", "Algorithm 1's heading, inputs, and loss term are corrected (Replacement 17); the post-aggregation validation/state-commitment sequence is clarified with explicit staging and commit semantics (Replacement 9). A full reproducibility package (configs, partitions, seeds, per-round scores, cohort selections, aggregation weights) cannot be produced without the original code and data; this is disclosed as outstanding (Replacement 22, item 8).", "disclosed"],
];
r1.forEach(([tag, c, r, k]) => children.push(...row(tag, c, r, k)));

children.push(h("Reviewer 2", HeadingLevel.HEADING_1));

const r2 = [
  ["R2-01", "Hidden communication/computation cost: all clients train and score every round; only uploads are reduced; Pow-D's probing cost is not counted.", "Same fix as R1-08: protocol explicitly states all-candidate download/train/score cost (Replacement 2); byte-level measurement is disclosed as not performed (Replacement 22, item 3).", "disclosed"],
  ["R2-02", "Reference rate (Eq. 11) depends on an unavailable prior baseline run; γ is undefined and unanalyzed.", "Fixed by Replacement 3 (causal self-reference; β_ref=0.9 specified, removes γ/baseline dependency).", "fixed"],
  ["R2-03", "Idle counter (Eq. 7) never increases for an unselected client.", "Same as R1-01; fixed by Replacement 4.", "fixed"],
  ["R2-04", "Control law denominator (Eq. 8) can reach zero/negative; λ never specified; “Lyapunov-inspired” unjustified.", "Denominator fixed (Replacement 6); λ=1 now specified; the Lyapunov framing is explicitly limited to a qualitative analogy with no stability proof claimed (Replacement 21).", "fixed"],
  ["R2-05", "Scale mismatch in Eq. (9): F≥1 is unbounded while ΔKL is typically ≪1, so fairness dominates regardless of α.", "Disclosed explicitly as a real design limitation, with the corrective direction (rescale both terms to a common range) identified but not revalidated experimentally (Replacement 21).", "disclosed"],
  ["R2-06", "Questionable utility definition: post-training KL measures client drift, which the FedProx/FedNova literature treats as harmful, not beneficial, under non-IID data; the sum over x∈X is ill-defined.", "Eq. (5) is rewritten with a precise class-probability definition and a stated scoring-batch procedure (Replacement 5). The underlying empirical question — whether higher ΔKL correlates with beneficial contribution for this method — is explicitly left open; the manuscript no longer asserts that high KL implies high utility without qualification.", "fixed"],
  ["R2-07", "Aggregation weights can be negative; dataset size n_i is dropped inconsistently with Eq. (1); Eq. (4) vs. Eq. (17) mismatch.", "Fixed by Replacement 8 (positive-part normalization with sample-count fallback) and Replacement 1 (clarifies Eq. 1 is the reference objective, not the aggregation rule's criterion).", "fixed"],
  ["R2-08", "Inconsistent time indexing (future losses required), mixed ρ^t/ρ^{t-1}, unspecified rounding, inconsistent N/K/C notation.", "Fixed by Replacement 3 (causal reference removes future-loss dependency) and Replacement 7 (integer rounding specified). Notation is unified to C_k^t for cohort size and C for the client population throughout (Replacement 17 extends this correction where flagged).", "fixed"],
  ["R2-09", "Cohort range (8–10) is too narrow to support the claimed ≈15% reduction (max possible is 20%), inconsistent with Fig. 4/Table 3 averages of 9.6–9.97.", "The unsupported ≈15% figure is removed from the ablation discussion; Replacement 7 states the bounds explicitly and Replacement 11 restates achieved reductions using the actual reported numbers only.", "fixed"],
  ["R2-10", "Itemized numerical inconsistencies (COVID-19 cohort exceeding cap, FMNIST cohort below floor, Table 4 recall/F1 implausibility, 83.08/83.80 mismatch, FedProx/Pow-D naming, 2.2%/2.8% rounding, Fig. 8/9 CIFAR-10 Random value mismatch, low CIFAR-10 accuracy vs. 10-class description).", "The textual/arithmetic items are corrected directly: 83.80% is used consistently, Pow-D naming is corrected, the round-reduction figure is corrected to 2.78% (Replacement 11); the CIFAR-10-vs-COVID-19 class-count issue is corrected (Replacement 18). The Configuration B bound disclosure and the Fig. 8/9 numeric discrepancy require the original figure-generation data to resolve with certainty; disclosed rather than guessed (Replacement 22, items 6 and 8). The Table 4 recall/F1 arithmetic plausibility (macro-recall should equal accuracy on balanced test sets) cannot be re-derived without raw confusion matrices; disclosed explicitly (Replacement 22, item 6).", "disclosed"],
  ["R2-11", "Misleading aggregate claims in the abstract: the 0.44% recall “improvement” averages a negative COVID-19 value; relative/absolute percentages are mixed; “best performing existing method” varies by configuration.", "Abstract rewritten to report per-configuration ranges, disclose the COVID-19 recall regression, and distinguish relative from absolute-point gains (Replacement 15).", "fixed"],
  ["R2-12", "No statistical rigor: apparent single-seed results; accuracy curves fluctuate ±4–5 points, making small reported differences within noise.", "Evaluation-endpoint protocol is tightened (Replacement 12); multi-seed statistical validation is disclosed as not performed (Replacement 22, item 1).", "disclosed"],
  ["R2-13", "Incomplete ablation: KL utility, fairness term, uncertainty penalty, and α-control are not isolated; FedFACS-A1 is slower than Zhai et al. on several settings, implying auxiliary components (not the core selection mechanism) drive the gains.", "Replacement 13 states this limitation directly in the ablation discussion, including the specific FedFACS-A1-vs-Zhai-et-al. comparison the reviewer cites. Targeted single-component ablations are disclosed as not performed (Replacement 22, item 2).", "disclosed"],
  ["R2-14", "Oort, FedCor, q-FFL/AFL, SCAFFOLD, FedNova are discussed but not evaluated; baseline reproduction provenance (re-run vs. copied numbers, same architecture or not) is unclear.", "Replacement 14 states exactly which methods are compared per configuration. Evaluating the discussed-but-untested baselines, and confirming reproduction provenance for every reported number, requires experiments we cannot run without the original setup; disclosed explicitly (Replacement 22, item 5).", "disclosed"],
  ["R2-15", "JFI is confounded with client data quality q_i; the 0.5 threshold is unfounded (minimum is 1/n); no client-level performance fairness (accuracy variance, worst-client accuracy) is reported; FedFACS trails FedFairCS in 2/6 Table 6 settings by small margins.", "The JFI interpretation and threshold claims are corrected (Replacement 16). Client-level accuracy variance and worst-client results are disclosed as not available (Replacement 22, item 4); the Table 6 mixed results are acknowledged directly in the corrected Conclusion (Replacement 18) rather than described as a uniform win.", "disclosed"],
  ["R2-16", "Only 30–100 clients tested, no scalability/runtime/memory analysis, no sensitivity analysis for β, λ, μ, γ, B, C_kmin, C_kmax; vague protocol (test vs. validation, stopping criterion, noise type in S3/S4).", "The evaluation-endpoint and data-split protocol is clarified (Replacement 12; Configuration A/C setting details in Replacement 12's continuation). Sensitivity and scalability analysis requires new experiments and is disclosed as not performed (Replacement 22, item 7).", "disclosed"],
  ["R2-17", "Fitness/stability scores are self-reported and unverified, making the scheme manipulable; deferring adversarial robustness to future work is insufficient given that selection and weighting rely on these values.", "A new explicit threat-model paragraph states this assumption directly and names candidate verification mechanisms as unimplemented future work (Replacement 20), rather than leaving it implicit.", "fixed"],
  ["R2-18", "No convergence guarantee or fairness bound is provided despite control-theoretic language.", "The manuscript now states explicitly that Eq. (8) is a bounded EMA feedback rule, not a Lyapunov function, and that no convergence rate or fairness bound is established (Replacement 21).", "fixed"],
  ["R2-19", "“Ignores clients with smaller datasets” (Sec. 4.1) states the opposite of the intended meaning.", "Wording corrected to “avoids permanently excluding” (Replacement 17).", "fixed"],
  ["R2-20", "Algorithm 1 is mistitled (it is client-side), L_local is undefined, input “C⊂C” is garbled, clip(a,1,0) has reversed bounds, Eqs. (1)–(2) mix indices i/j.", "All four corrected: Algorithm 1 retitled and its input/loss term defined; clip bounds corrected to clip(a,0,1); Eq. (2) indexing corrected (Replacement 17).", "fixed"],
  ["R2-21", "Reference list issues: He et al. 2021 vs. 2016; MNIST/FMNIST not cited in text; ref. [29] irrelevant; market-size unit conflict (million vs. billion); Lyapunov reference from power engineering.", "All corrected or clarified in Replacement 19 (citation year fixed, irrelevant reference removed, MNIST/FMNIST added as in-text citations, market-size units corrected and attributed to a press release, Lyapunov reference scope clarified).", "fixed"],
  ["R2-22", "The Conclusion omits COVID-19 from the dataset list; claims such as “ensures fairness” and “each component is crucial” exceed the evidence.", "Conclusion rewritten to name all four datasets and scope its claims to what Sections 5.3's tables actually show (Replacement 18).", "fixed"],
  ["R2-23", "No code, data splits, or seeds are provided; a reproducibility statement is needed.", "A reproducibility statement is added (Replacement 22, item 8), disclosing directly that the code and dataset used to produce the reported results are not available to be released with this revision, and naming what a future reproducibility package would need to contain.", "disclosed"],
];
r2.forEach(([tag, c, r, k]) => children.push(...row(tag, c, r, k)));

children.push(h("Summary", HeadingLevel.HEADING_1));
children.push(p(`Of the 44 individually numbered reviewer points (21 from Reviewer 1, 23 from Reviewer 2), 25 are resolved directly through corrected mathematics, protocol description, terminology, or wording (no new data required), and 19 concern claims that can only be substantiated with the original code, datasets, logs, or additional training runs. For the latter group, the manuscript no longer asserts the disputed claim; instead, Section 5.4 (Limitations and Reproducibility Statement, Replacement 22) discloses the gap explicitly and states what evidence would be needed to close it. We believe this response gives the editor and reviewers an accurate, auditable account of exactly what has changed and what remains open, rather than a revision that appears complete without being verifiable.`));

const doc = new Document({
  sections: [{ properties: { page: { size: { width: 12240, height: 15840 } } }, children }],
  styles: {
    default: {
      heading1: { run: { font: "Calibri", size: 32, bold: true }, paragraph: { spacing: { before: 280, after: 140 }, keepNext: true } },
      heading2: { run: { font: "Calibri", size: 26, bold: true }, paragraph: { spacing: { before: 220, after: 100 }, keepNext: true } },
      document: { run: { font: "Calibri", size: 22 } },
    },
  },
});

Packer.toBuffer(doc).then((buf) => {
  require("fs").writeFileSync("FedFACS_Response_to_Reviewers.docx", buf);
  console.log("written");
});

