const { Document, Packer, Paragraph, TextRun, HeadingLevel } = require("docx");

function h(text, level) {
  return new Paragraph({ text, heading: level, spacing: { before: 240, after: 120 }, keepNext: true });
}
function p(text, opts = {}) {
  return new Paragraph({ children: [new TextRun({ text, ...opts })], spacing: { before: 0, after: 80 } });
}
function row(tag, comment, resolution, kind) {
  const out = [];
  out.push(new Paragraph({ children: [new TextRun({ text: `${tag}. `, bold: true }), new TextRun({ text: comment, italics: true })], spacing: { before: 160, after: 40 } }));
  const tagText = kind === "fixed" ? "Resolved — " : kind === "disclosed" ? "Disclosed as limitation — " : "Resolved (text/notation only) — ";
  out.push(new Paragraph({ children: [new TextRun({ text: tagText, bold: true }), new TextRun({ text: resolution })], spacing: { after: 100 } }));
  return out;
}

const children = [];
children.push(new Paragraph({ text: "Response to Reviewers — FedFACS", heading: HeadingLevel.TITLE, spacing: { after: 80 } }));
children.push(p("Manuscript: \u201CFedFACS: A Fair Adaptive Client Selection Framework for Communication-Efficient Federated Learning\u201D, Journal of King Saud University \u2014 Computer and Information Sciences.", { italics: true }));
children.push(p("We thank both reviewers for a detailed and technically precise review. Every point raised is addressed below. Points that concern the mathematical formulation, algorithm description, terminology, or interpretation of existing results are corrected directly (via the numbered Replacements in the accompanying revision documents). Points that require new experiments, additional seeds, raw confusion matrices, per-round logs, or code/data that are not currently available to us are not answered with invented numbers; they are instead disclosed explicitly in the new Limitations and Reproducibility Statement (Replacement 22) and flagged below as such. We believe this is the only honest way to respond to those specific requests at this time, and we have scoped the manuscript's claims so that they do not exceed what the reported evidence supports.", { bold: true }));

children.push(h("Reviewer 1", HeadingLevel.HEADING_1));

const r1 = [
  ["R1-01", "Equation (7) never increments the idle-round counter for an unselected client, so the fairness mechanism as written cannot produce the described behavior.", "Eq. (7) is corrected: unselected clients increment their counter by 1, selected clients reset to 0 (Replacement 4).", "fixed"],
  ["R1-02", "The control law denominator in Eq. (8) can be zero or negative, and the claimed direction of the feedback does not hold in general.", "The denominator is changed to \u03bbF_i^t, which is always positive since F\u2265 1 (Replacement 6). The directional claim is also corrected to state that the sign depends jointly on \u03bd^t and (\u0394KL_i^t\u2212F_i^t), not on \u03bd^t alone.", "fixed"],
  ["R1-03", "The stability-weighted aggregation permits negative weights, the normalization in Eq. (18) does not guarantee nonnegative weights or a nonzero denominator, and Eq. (4)/Algorithm 2 use unnormalized scores while Eqs. (17)\u2013(18) use normalized ones.", "Aggregation is redefined using the positive part of each raw score with a sample-count fallback when the sum of positive parts is zero (Replacement 8). Eqs. (4) and (17) are stated to use the same weighted average.", "fixed"],
  ["R1-04", "The utility interpretation (expected reduction in KL divergence) is not supported by the actual definition, which measures post-training disagreement, not a before/after reduction.", "Eq. (5) and surrounding text are corrected to describe \u0394KL as a measure of post-training local/global disagreement, not a reduction or evidence of improvement (Replacement 5).", "fixed"],
  ["R1-05", "The uncertainty penalty (batch variance) does not clearly distinguish noisy/corrupted data from legitimate heterogeneity.", "The interpretive text is corrected to state only what the variance term measures (dispersion across scoring batches), without the unsupported claim that low variance establishes reliability (Replacement 5). Whether the penalty actually discriminates corrupted from heterogeneous-but-useful updates is an empirical question; we do not have the ability to test this without the original client data pipelines, so it is disclosed as an open item in the Limitations section (Replacement 22, item 2).", "disclosed"],
  ["R1-06", "The cohort-size rule (Eqs. 15\u201316) can produce invalid (negative, non-integer, out-of-bound) cohort sizes.", "Eq. (16) now clips the loss ratio and rounds to the nearest integer within [C_kmin, C_kmax] (Replacement 7); Eq. (15) is redefined as a causal, bounded quantity (Replacement 3).", "fixed"],
  ["R1-07", "The reference convergence trajectory (Eq. 11) depends on a prior run of a competing baseline, which is unavailable in practice and creates circularity with the comparison.", "Eq. (11) is replaced with a causal self-reference computed from FedFACS's own prior rounds via an exponential moving average, removing the dependency on a competitor's trajectory (Replacement 3).", "fixed"],
  ["R1-08", "The communication-efficiency claim is not established by counting only aggregated updates; all candidates download the model and train locally regardless of final selection.", "The protocol description now explicitly states that all N candidates incur download, training, and scoring costs, and that only upload is reduced (Replacement 2). The resource-accounting equations are extended to define download/upload/auxiliary traffic terms (Replacement 10). Measuring and reporting actual byte-level costs requires re-running the experiments with instrumentation that does not exist in the recovered materials; this is disclosed explicitly rather than estimated (Replacement 22, item 3).", "disclosed"],
