import zipfile, sys, re
import xml.etree.ElementTree as ET

M = "http://schemas.openxmlformats.org/officeDocument/2006/math"
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
def q(ns, t): return "{%s}%s" % (ns, t)

def kids(el, tag):
    return [c for c in el if c.tag == q(M, tag)]
def first(el, tag):
    for c in el:
        if c.tag == q(M, tag):
            return c
    return None

def conv(el):
    if el is None:
        return ""
    t = el.tag
    ln = t.split('}')[1] if '}' in t else t
    if ln == 'r':
        return "".join((x.text or "") for x in el.iter(q(M, 't')))
    if ln == 'f':
        return "\\frac{%s}{%s}" % (conv(first(el, 'num')), conv(first(el, 'den')))
    if ln == 'sSub':
        return "{%s}_{%s}" % (conv(first(el, 'e')), conv(first(el, 'sub')))
    if ln == 'sSup':
        return "{%s}^{%s}" % (conv(first(el, 'e')), conv(first(el, 'sup')))
    if ln == 'sSubSup':
        return "{%s}_{%s}^{%s}" % (conv(first(el, 'e')), conv(first(el, 'sub')), conv(first(el, 'sup')))
    if ln == 'nary':
        pr = first(el, 'naryPr'); chr_ = '\\int'
        if pr is not None:
            c = first(pr, 'chr')
            if c is not None:
                chr_ = c.get(q(M, 'val'))
        return "%s_{%s}^{%s}{%s}" % (chr_, conv(first(el, 'sub')), conv(first(el, 'sup')), conv(first(el, 'e')))
    if ln == 'd':
        pr = first(el, 'dPr'); b, e = '(', ')'
        if pr is not None:
            bc = first(pr, 'begChr'); ec = first(pr, 'endChr')
            if bc is not None: b = bc.get(q(M, 'val'))
            if ec is not None: e = ec.get(q(M, 'val'))
        return "%s%s%s" % (b, ",".join(conv(x) for x in kids(el, 'e')), e)
    if ln == 'func':
        return "%s(%s)" % (conv(first(el, 'fName')), conv(first(el, 'e')))
    if ln == 'acc':
        return "acc[%s]{%s}" % ("", conv(first(el, 'e')))
    if ln == 'bar':
        return "bar{%s}" % conv(first(el, 'e'))
    if ln == 'rad':
        return "sqrt{%s}" % conv(first(el, 'e'))
    if ln == 'limLow':
        return "{%s}_{%s}" % (conv(first(el, 'e')), conv(first(el, 'lim')))
    if ln == 'limUpp':
        return "{%s}^{%s}" % (conv(first(el, 'e')), conv(first(el, 'lim')))
    if ln == 'eqArr':
        return " ;; ".join(conv(x) for x in kids(el, 'e'))
    if ln == 'm':
        rows = []
        for mr in kids(el, 'mr'):
            rows.append(" & ".join(conv(x) for x in kids(mr, 'e')))
        return "matrix[" + " \\\\ ".join(rows) + "]"
    if ln in ('oMath', 'oMathPara', 'e', 'num', 'den', 'sub', 'sup', 'fName', 'lim', 'deg'):
        return "".join(conv(c) for c in el)
    if ln.endswith('Pr'):
        return ""
    return "".join(conv(c) for c in el)

def para_text(p):
    out = []
    def walk(el):
        for c in el:
            ln = c.tag.split('}')[1] if '}' in c.tag else c.tag
            if c.tag == q(M, 'oMath'):
                out.append(" [[" + conv(c) + "]] ")
            elif c.tag == q(M, 'oMathPara'):
                for om in c:
                    if om.tag == q(M, 'oMath'):
                        out.append(" [[" + conv(om) + "]] ")
            elif c.tag == q(W, 't'):
                out.append(c.text or "")
            elif c.tag == q(W, 'tab'):
                out.append("\t")
            else:
                walk(c)
    walk(p)
    return "".join(out)

def main(path, outpath):
    z = zipfile.ZipFile(path)
    root = ET.fromstring(z.read('word/document.xml'))
    body = root.find(q(W, 'body'))
    lines = []
    def descend(el):
        for c in el:
            if c.tag == q(W, 'p'):
                lines.append(para_text(c))
            elif c.tag == q(W, 'tbl'):
                descend(c)
            else:
                descend(c)
    descend(body)
    with open(outpath, 'w', encoding='utf-8') as f:
        f.write("\n".join(lines))
    print(len(lines), "paragraphs")

main(sys.argv[1], sys.argv[2])

