import numpy as np
import analyze as A

rows = A.load()
M = {}
for ds, sc, me, seed, tag, r in rows:
    if tag == "" and sc == "s1_0.5" and ds in ("fmnist", "cifar10"):
        M[(ds, me, seed)] = A.run_metrics(r)
rng = np.random.default_rng(0)


def ci(d):
    d = np.asarray(d, float)
    b = rng.choice(d, (10000, len(d))).mean(1)
    return "%+.2f [%+.2f,%+.2f]" % (d.mean(), np.percentile(b, 2.5), np.percentile(b, 97.5))


for ref in ("random", "fedfacs"):
    print("\nabl_A2 (FedFACS selection + adaptive cohort + sample-count weights) MINUS", ref, "(paired by seed, fmnist+cifar10, s1_0.5)")
    keys = [(d, s) for d in ("fmnist", "cifar10") for s in range(3) if (d, "abl_A2", s) in M and (d, ref, s) in M]
    for m in ("acc_best", "acc_last10", "pc_p10", "macro_f1", "jitter", "jfi", "max_wait"):
        d = [M[(a, "abl_A2", s)][m] - M[(a, ref, s)][m] for a, s in keys]
        print("  %-10s n=%d  %s" % (m, len(keys), ci(d)))
print("\nabsolute means (A2 / random / fedfacs):")
for m in ("acc_best", "acc_last10", "jitter", "jfi", "max_wait", "down_gb"):
    vals = []
    for me in ("abl_A2", "random", "fedfacs"):
        v = [M[(d, me, s)][m] for d in ("fmnist", "cifar10") for s in range(3) if (d, me, s) in M]
        vals.append(np.mean(v))
    print("  %-10s A2 %.3f | random %.3f | fedfacs %.3f" % (m, *vals))

