"""Readable Word version of the exact edits: plain text + native Word equations, location, red (remove) / green (new) highlights."""
import json, re, difflib, os, subprocess
import pypandoc
from docx import Document
from docx.enum.style import WD_STYLE_TYPE
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Pt, RGBColor, Inches

SP = os.path.dirname(os.path.abspath(__file__))
ORIG = open(r"C:\Users\0xRay\Downloads\paper\paper_overleaf\sn-article.tex", encoding="utf8").read().replace("\r\n", "\n")
edits = json.load(open(os.path.join(SP, "edits.json"), encoding="utf8"))
by_tag = {e["tag"]: e for e in edits}
OUT = r"C:\Users\0xRay\Downloads\paper\FedFACS_Before_After_Locations.docx"

GROUPS = [
    ("Replacement 1. Learning objective, selection rule and indices", ["R1-section3"]),
    ("Replacement 2. Round protocol, Algorithms 1-2 and operating assumptions",
     ["R2-wording", "R2-protocol", "R2-alg1-text", "R2-alg1", "R2-alg2", "R2-alg2-text", "R2-trust"]),
    ("Replacement 3. Deviation signal and causal reference (Eqs. 10-11)", ["R3-reference"]),
    ("Replacement 4. Idle counter (Eq. 7)", ["R4-idle"]),
    ("Replacement 5. KL utility, variance and stability score (Eqs. 5, 12-14)",
     ["abstract-1", "abstract-2", "intro-kl", "R5-kl", "R5-variance-fitness"]),
    ("Replacement 6. Feedback controller and priority (Eqs. 8-9)", ["intro-lyapunov", "R6-controller"]),
    ("Replacement 7. Cohort size (Eqs. 15-16)", ["R7-cohort"]),
    ("Replacements 8-9. Aggregation weights, commit and Eq. 19", ["R8-R9-aggregation"]),
    ("Replacement 10. Metrics and communication accounting", ["R10-round-to-accuracy", "R10-metrics"]),
    ("Clean-up. Wording, citations and reference list",
     ["intro-domination", "intro-market-sentence-removed", "intro-cha", "related-li2016", "he2016", "datasets-cite",
      "bib-removed-ref13", "bib-removed-ref29"] + ["rename-%d" % k for k in range(1, 9)]),
]
SECTION = [(0, "Abstract"), (120, "1 Introduction"), (150, "2 Related work"), (180, "3 Problem formulation"),
           (226, "4.1 Framework overview and algorithms"), (351, "4.2 Proposed approach"),
           (476, "5 Experimental setup"), (1170, "References")]


def section(line):
    name = SECTION[0][1]
    for ln, nm in SECTION:
        if line >= ln:
            name = nm
    return name


# ------------------------------------------------------------------ LaTeX -> text helpers
def fix_math(m):
    m = m.strip()
    m = m.replace(r"\textit{", r"\mathit{").replace(r"\displaystyle", "")
    m = re.sub(r"\\substack\{(.*?)\\\\(.*?)\}", r"\1,\\ \2", m)
    m = re.sub(r"\\\\\[[^\]]*\]", r"\\\\", m)
    m = m.replace(r"\left|", "@L@").replace(r"\right|", "@R@")
    m = re.sub(r"(?<!\\)\|([^|@]*)\|", r"\\left|\1\\right|", m)
    m = m.replace("@L@", r"\left|").replace("@R@", r"\right|")
    return m.strip()


def strip_cmds(t):
    for _ in range(4):
        t = re.sub(r"\\text(?:it|bf)\{([^{}]*)\}", r"\1", t)
    t = re.sub(r"\\url\{([^{}]*)\}", r"\1", t)
    t = re.sub(r"\\label\{[^{}]*\}", "", t)
    t = re.sub(r"\\bibitem\{[^{}]*\}\s*", "", t)
    t = t.replace("~", " ").replace("``", "\u201c").replace("''", "\u201d").replace(r"\%", "%").replace(r"\&", "&").replace(r"\_", "_")
    t = t.replace("--", "\u2013")
    return t


def segs(text):
    """split into [(is_math, str)] after command stripping; collapse whitespace outside math"""
    text = strip_cmds(text)
    parts = text.split("$")
    out = []
    for k, p in enumerate(parts):
        if k % 2:
            out.append((True, fix_math(p)))
        else:
            out.append((False, re.sub(r"\s+", " ", p)))
    return out


def tokens(text):
    toks = []
    for is_math, s in segs(text):
        if is_math:
            toks.append((s, True))
        else:
            for t in re.findall(r"\s+|\w+|[^\w\s]", s):
                toks.append((t, False))
    # trim
    while toks and not toks[0][1] and toks[0][0].isspace():
        toks.pop(0)
    while toks and not toks[-1][1] and toks[-1][0].isspace():
        toks.pop()
    return toks


def esc(t):
    return re.sub(r"([\\`*_{}\[\]<>#|~^])", r"\\\1", t)


def render(tok):
    s, is_math = tok
    return "$" + s + "$" if is_math else esc(s)


def plain_md(text):
    return "".join(render(t) for t in tokens(text))


def plain_words(text, n, tail=False):
    toks = tokens(text)
    s = "".join("\u2026" if m else t for t, m in toks)
    w = s.split()
    return " ".join(w[-n:] if tail else w[:n])


# ------------------------------------------------------------------ blocks
def parse_blocks(text, eq_start):
    text = "\n".join(l for l in text.split("\n") if not re.match(r"^\s*%", l))
    blocks, pos, n = [], 0, eq_start
    pat = re.compile(r"\\begin\{equation\}(.*?)\\end\{equation\}|\\begin\{tabular\}\{[^\n]*\}(.*?)\\end\{tabular\}", re.S)

    def paras(chunk):
        chunk = re.sub(r"\\(?:par|noindent)\b", "", chunk)
        chunk = re.sub(r"\\rule\{[^}]*\}\{[^}]*\}", "", chunk)
        chunk = re.sub(r"\\vspace\{[^}]*\}", "", chunk)
        for p in re.split(r"\n\s*\n", chunk):
            if p.strip():
                blocks.append(["p", p.strip()])

    for m in pat.finditer(text):
        paras(text[pos:m.start()])
        pos = m.end()
        if m.group(1) is not None:
            body = m.group(1)
            tag = re.search(r"\\tag\{([^}]*)\}", body)
            body = re.sub(r"\\tag\{[^}]*\}|\\label\{[^}]*\}", "", body)
            body = re.sub(r"\s+", " ", body).strip()
            if tag:
                lab = tag.group(1)
            else:
                lab = str(n)
                n += 1
            blocks.append(["eq", fix_math(body), lab])
        else:
            rows = []
            for r in re.split(r"\\\\\s*\n", m.group(2).strip()):
                r = r.strip()
                if not r or "&" not in r:
                    continue
                num, body = r.split("&", 1)
                ind = sum(float(x) for x in re.findall(r"\\hspace\{([\d.]+)em\}", body))
                body = re.sub(r"\\hspace\{[^}]*\}", "", body)
                body = re.sub(r"\\\\\[[^\]]*\]", " ", body).replace("\\\\", " ")
                body = re.sub(r"\\textbf\{([^{}]*)\}", r"@B@\1@E@", body)
                rows.append((num.strip(), int(round(ind * 2)), body.strip()))
            blocks.append(["rows", rows])
    paras(text[pos:])
    return blocks


def key(b):
    if b[0] == "p":
        return "p|" + "".join(t for t, _ in tokens(b[1]))
    if b[0] == "eq":
        return "eq|" + b[1].replace(" ", "")
    return "rows|" + "|".join(r[0] + re.sub(r"\s+", "", r[2]) for r in b[1])


def row_md(r):
    num, ind, body = r
    segs_ = segs(body.replace("@B@", "").replace("@E@", ""))
    txt = "".join("$" + s + "$" if m else esc(s) for m, s in segs_)
    return "\u00a0" * ind + esc(num) + " " + txt.strip()


def row_key(r):
    return r[0] + re.sub(r"\s+", "", r[2])


# ------------------------------------------------------------------ marking
def div(style, inner):
    return '::: {custom-style="%s"}\n%s\n:::\n' % (style, inner)


def pdiff(old, new):
    a, b = tokens(old), tokens(new)
    sm = difflib.SequenceMatcher(None, [t for t, _ in a], [t for t, _ in b], autojunk=False)
    ao, bo = ["eq"] * len(a), ["eq"] * len(b)
    for op, i1, i2, j1, j2 in sm.get_opcodes():
        if op != "equal":
            for i in range(i1, i2):
                ao[i] = "del"
            for j in range(j1, j2):
                bo[j] = "add"

    def fill(toks, ops):
        for i, (t, m) in enumerate(toks):
            if ops[i] == "eq" and not m and t.isspace() and 0 < i < len(toks) - 1 and ops[i - 1] == ops[i + 1] != "eq":
                ops[i] = ops[i - 1]
    fill(a, ao)
    fill(b, bo)

    def emit(toks, ops, style):
        out, i, ch = [], 0, []
        while i < len(toks):
            j = i
            while j < len(toks) and ops[j] == ops[i]:
                j += 1
            seg = toks[i:j]
            txt = "".join(render(t) for t in seg)
            if ops[i] == "eq":
                out.append(txt)
            else:
                pad = "\u00a0" if any(m for _, m in seg) else ""
                lead = txt[: len(txt) - len(txt.lstrip())]
                trail = txt[len(txt.rstrip()):]
                out.append(lead + "[" + pad + txt.strip() + pad + "]{custom-style=\"%s\"}" % style + trail)
                ch.append(seg)
            i = j
        return "".join(out), ch
    om, och = emit(a, ao, "Del")
    nm, nch = emit(b, bo, "Add")
    return om, nm, och, nch


def sim(a, b):
    return difflib.SequenceMatcher(None, a, b, autojunk=False).quick_ratio()


def mark(oblocks, nblocks):
    ok, nk = [key(b) for b in oblocks], [key(b) for b in nblocks]
    sm = difflib.SequenceMatcher(None, ok, nk, autojunk=False)
    omd, nmd = [None] * len(oblocks), [None] * len(nblocks)  # each: ("eq"|"del"|"add"|"mix", md)
    removed, added = [], []

    def tstr(seg):
        return " ".join(("$%s$" % t if m else esc(t)) for t, m in seg).replace("  ", " ")

    def whole(b, which):
        if b[0] == "p":
            return plain_md(b[1])
        if b[0] == "eq":
            return "$$" + b[1] + r"\qquad (" + b[2] + ")$$"
        return None

    for op, i1, i2, j1, j2 in sm.get_opcodes():
        if op == "equal":
            for k in range(i2 - i1):
                omd[i1 + k] = ("eq", i1 + k)
                nmd[j1 + k] = ("eq", j1 + k)
            continue
        used = set()
        for i in range(i1, i2):
            best, bj = 0.5, None
            for j in range(j1, j2):
                if j in used or nblocks[j][0] != oblocks[i][0]:
                    continue
                if oblocks[i][0] == "p":
                    s = sim(ok[i], nk[j])
                elif oblocks[i][0] == "rows":
                    s = 1.0
                else:
                    s = 0.0
                if s > best:
                    best, bj = s, j
            if bj is None:
                omd[i] = ("del", i)
            else:
                used.add(bj)
                omd[i] = ("pair", i, bj)
                nmd[bj] = ("pair", i, bj)
        for j in range(j1, j2):
            if nmd[j] is None:
                nmd[j] = ("add", j)

    def block_md(b, style, label_override=None):
        if b[0] == "eq":
            return div(style, "$$" + b[1] + r"\qquad (" + b[2] + ")$$")
        return div(style, plain_md(b[1]))

    outO, outN = [], []
    for i, m in enumerate(omd):
        b = oblocks[i]
        if m[0] == "eq":
            outO.append(block_md(b, "BA-Text"))
        elif m[0] == "del":
            outO.append(block_md(b, "DelBlock") if b[0] != "rows" else "".join(div("DelBlock", row_md(r)) for r in b[1]))
            removed.append(("blk", b))
        else:
            j = m[2]
            nb = nblocks[j]
            if b[0] == "p":
                om, nm, och, nch = pdiff(b[1], nb[1])
                outO.append(div("BA-Text", om))
                nmd[j] = ("pairmd", nm)
                removed += [("run", c) for c in och]
                added += [("run", c) for c in nch]
            else:  # rows
                ak, bk = [row_key(r) for r in b[1]], [row_key(r) for r in nb[1]]
                s2 = difflib.SequenceMatcher(None, ak, bk, autojunk=False)
                ol, nl = ["BA-Text"] * len(b[1]), ["BA-Text"] * len(nb[1])
                for op, i1, i2, j1, j2 in s2.get_opcodes():
                    if op != "equal":
                        for x in range(i1, i2):
                            ol[x] = "DelBlock"
                            removed.append(("row", b[1][x]))
                        for x in range(j1, j2):
                            nl[x] = "AddBlock"
                            added.append(("row", nb[1][x]))
                outO.append("".join(div(ol[x], row_md(r)) for x, r in enumerate(b[1])))
                nmd[j] = ("pairrows", "".join(div(nl[x], row_md(r)) for x, r in enumerate(nb[1])))
    for j, m in enumerate(nmd):
        b = nblocks[j]
        if m[0] == "eq":
            outN.append(block_md(b, "BA-Text"))
        elif m[0] == "add":
            outN.append(block_md(b, "AddBlock") if b[0] != "rows" else "".join(div("AddBlock", row_md(r)) for r in b[1]))
            added.append(("blk", b))
        elif m[0] == "pairmd":
            outN.append(div("BA-Text", m[1]))
        elif m[0] == "pairrows":
            outN.append(m[1])
        else:  # 'pair' not yet resolved (should not happen)
            outN.append(block_md(b, "AddBlock"))
    return outO, outN, removed, added


def bullets(items, limit=8):
    out = []
    for kind, v in items:
        if kind == "run":
            words = [t for t, m in v if not t.isspace()]
            if len(words) < 3 and not any(m for _, m in v):
                continue
            s = "".join(render(t) for t in v).strip()
            toks = v
            if len(toks) > 28:
                s = "".join(render(t) for t in toks[:28]).strip() + " \u2026"
            out.append(s)
        elif kind == "row":
            out.append("Algorithm line " + esc(v[0]) + ": " + row_md(("", 0, v[2])).strip())
        else:
            b = v
            if b[0] == "eq":
                out.append("Equation (" + b[2] + "): $" + b[1] + "$")
            elif b[0] == "p":
                t = tokens(b[1])
                s = "".join(render(x) for x in t[:34]).strip()
                out.append("Paragraph: " + s + (" \u2026" if len(t) > 34 else ""))
            else:
                out.append("Algorithm steps block")
    seen, res = set(), []
    for s in out:
        if s not in seen:
            seen.add(s)
            res.append(s)
    return res[:limit]


# ------------------------------------------------------------------ per-edit assembly
def context(e):
    old = e["old"]
    if len(old) >= 700 or "\\begin{equation}" in old or "\\bibitem" in old or "tabular" in old or e["tag"].startswith("rename"):
        return "", ""
    i = ORIG.index(old)
    a = ORIG.rfind("\n\n", 0, i) + 2 if ORIG.rfind("\n\n", 0, i) != -1 else 0
    a = max(a, i - 160)
    b_end = i + len(old)
    nxt = ORIG.find("\n\n", b_end)
    b = min(nxt if nxt != -1 else len(ORIG), b_end + 160)
    pre, post = ORIG[a:i], ORIG[b_end:b]
    if a > 0 and ORIG[a - 1] not in "\n ":
        pre = pre[pre.find(" ") + 1:] if " " in pre else pre
    if b < len(ORIG) and ORIG[b:b + 1] not in "\n ":
        post = post[:post.rfind(" ")] if " " in post else post
    pre = "\u2026" + pre if a > 0 and not pre.startswith("\n") else pre
    return pre, post + "\u2026"


md = ['::: {custom-style="BA-Title"}\nFedFACS \u2014 Before / After with exact locations in sn-article.tex\n:::\n']
md.append(div("BA-Note", "Each edit shows where it sits in your original Overleaf file, the text to remove (Before) and the text to put in its place (After)."))
md.append(div("BA-Legend", '[ red, struck-through ]{custom-style="Del"} = text you remove.  [ green ]{custom-style="Add"} = new text you add.  No colour = unchanged, keep it. Where an equation changes, the whole equation line is shaded; a shaded gap next to a formula marks a changed formula inside a sentence.'))
md.append(div("BA-Note", "Line numbers are those of your ORIGINAL sn-article.tex. Equation numbers stay (1)\u2013(25); new equations carry the labels (5a), (5b), (12a), (23a). The same edits are already applied in paper_overleaf_revised/sn-article.tex."))

stats = []
for gi, (gtitle, tags) in enumerate(GROUPS, 1):
    items = [by_tag[t] for t in tags if t in by_tag]
    items.sort(key=lambda e: e["line"])
    md.append("\n# " + gtitle + "\n")
    for n, e in enumerate(items, 1):
        old, new = e["old"], e["new"]
        line = e["line"]
        end_line = line + old.count("\n")
        eq_start = ORIG[:ORIG.index(old)].count("\\begin{equation}") + 1 if old in ORIG else 1
        pre, post = context(e)
        oblocks = parse_blocks(pre + old + post, eq_start) if not pre + post else parse_blocks(pre + old + post, eq_start)
        nblocks = parse_blocks(pre + new + post, eq_start)
        if e["tag"].startswith("rename"):
            oblocks, nblocks = parse_blocks(old, 1), parse_blocks(new, 1)
        outO, outN, removed, added = mark(oblocks, nblocks)
        loc = "%s \u2014 original line %d" % (section(line), line) if end_line == line else "%s \u2014 original lines %d\u2013%d" % (section(line), line, end_line)
        md.append('::: {custom-style="BA-Edit"}\nEdit %d.%d \u00b7 %s\n:::\n' % (gi, n, loc))
        if e["tag"].startswith("rename"):
            md.append(div("BA-Loc", "Replace the word FedFairCS with FairFedCS (the method is FairFedCS, arXiv 2307.10738)."))
        else:
            first = oblocks[0] if oblocks else None
            last = oblocks[-1] if oblocks else None

            def anchor(b, tail):
                if b is None:
                    return ""
                if b[0] == "eq":
                    return "Equation (" + b[2] + ")"
                if b[0] == "rows":
                    return "the last algorithm step"
                return "\u201c" + ("\u2026" if tail else "") + esc(plain_words(b[1], 9, tail)) + ("" if tail else "\u2026") + "\u201d"
            if pre or post:
                src = oblocks
                fi = [b for b in oblocks if b[0] == "p"]
                md.append(div("BA-Loc", "Find this passage (the highlighted words are the part that changes):"))
            else:
                md.append(div("BA-Loc", "Starts at " + anchor(first, False) + " \u00b7 ends at " + anchor(last, True) + ". Select everything between and replace it with the After block."))
        md.append(div("BA-Label-Before", "Before \u2014 remove"))
        md.append("".join(outO))
        md.append(div("BA-Label-After", "After \u2014 put instead" if new.strip() else "After \u2014 nothing: delete the text above"))
        md.append("".join(outN) if new.strip() else div("BA-Text", "(removed completely)"))
        rb, ab = bullets(removed), bullets(added)
        if (rb or ab) and not e["tag"].startswith("rename"):
            if rb:
                md.append(div("BA-Sub", "What is removed"))
                md.append("\n".join("- " + b for b in rb) + "\n")
            if ab:
                md.append(div("BA-Sub", "What is added"))
                md.append("\n".join("- " + b for b in ab) + "\n")
        stats.append(e["tag"])

md.append("\n# Not changed by these edits\n")
md.append("- Replacements 11\u201314 (tables, Table 4 recall/F1, Table 5 cohort cap, baseline naming) depend on the recomputed numbers in the results report and on the Zhai et al. / AHIBCS PDFs.\n"
          "- Abstract numbers, the contribution list, the conclusion and the ablation discussion still contain claims the experiments do not support; recommended framing: fairness bought with extra compute.\n"
          "- Author, funding and conflict-of-interest fields, and the values lambda, mu, a0, B and the cohort bounds, must be confirmed by the authors.\n"
          "- References mukhtiar2025b and huang2020 still need their metadata verified.\n")

SRC = os.path.join(SP, "edits_word.md")
open(SRC, "w", encoding="utf8").write("\n".join(md))

# ------------------------------------------------------------------ styles + pandoc
REF, TMP = os.path.join(SP, "ref_loc.docx"), os.path.join(SP, "loc_tmp.docx")
subprocess.run([pypandoc.get_pandoc_path(), "-o", REF, "--print-default-data-file", "reference.docx"], check=True)
